namespace Hexalith.Platform.Composition;

using System.Globalization;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using Hexalith.Builds.Tooling.Manifest;
using YamlDotNet.RepresentationModel;

/// <summary>Resolves the shared Dapr capability graph before resources exist.</summary>
public sealed class PlatformDaprBindings
{
    private PlatformRetentionProfile? _retentionProfile;
    private readonly Dictionary<string, (string Kind, string Recovery, string Template, HashSet<string> Consumers)> _components = new(StringComparer.Ordinal);
    private readonly Dictionary<string, Dictionary<string, string>> _environment = new(StringComparer.Ordinal);
    private readonly Dictionary<string, List<(string Caller, string Path, string[] Verbs)>> _rules = new(StringComparer.Ordinal);
    private readonly List<(string Name, string Component, string Topic, string Route, string AppId, string? DeadLetter)> _subscriptions = [];

    /// <summary>Gets resolved component names.</summary>
    public IEnumerable<string> ComponentNames => _components.Where(component => component.Value.Consumers.Count > 0).Select(component => component.Key);

    /// <summary>Resolves all selected declarations atomically.</summary>
    public static PlatformDaprBindings Resolve(IReadOnlyList<PlatformModuleDeclaration> declarations, PlatformRetentionProfile? retentionProfile = null)
    {
        ArgumentNullException.ThrowIfNull(declarations);
        PlatformDaprBindings result = new() { _retentionProfile = retentionProfile };
        foreach (PlatformModuleDeclaration module in declarations)
        {
            string owner = PlatformDeclarationSet.Id(module.Declaration);
            Dictionary<string, string> servers = module.Declaration.GetProperty("identity").GetProperty("servers").EnumerateArray()
                .Where(server => server.GetProperty("enabled").GetBoolean()).ToDictionary(server => server.GetProperty("id").GetString()!, server => server.GetProperty("appId").GetString()!, StringComparer.Ordinal);
            foreach (var server in servers)
            {
                result._environment.Add(owner + "/" + server.Key, new(StringComparer.OrdinalIgnoreCase));
                result._rules.Add(server.Value, []);
            }
            foreach (JsonElement capability in module.Declaration.GetProperty("runtime").GetProperty("dapr").EnumerateArray())
            {
                string role = capability.GetProperty("role").GetString()!;
                string kind = capability.GetProperty("capability").GetString()!;
                string recovery = capability.GetProperty("recoveryClass").GetString()!;
                string template = (kind, role) switch
                {
                    ("state", "state") => "statestore.yaml", ("pubsub", "events") => "pubsub.yaml",
                    ("configuration", "rate-limit-configuration") => "configstore.yaml",
                    ("state", "telemetry-state") => "telemetry-state.yaml",
                    ("configuration", "telemetry-configuration") => "telemetry-config.yaml",
                    ("secret", "secrets" or "telemetry-secrets") => "secretstore.yaml",
                    ("conversation", "conversation") => "llm.yaml",
                    _ => throw Failure(module, "runtime.dapr", $"unsupported capability '{kind}' with role '{role}'"),
                };
                string name = Name(kind, role);
                if (result._components.TryGetValue(name, out var existing) && (existing.Kind != kind || existing.Recovery != recovery))
                    throw Failure(module, "runtime.dapr", $"conflicting recovery class for component '{name}'");
                if (!result._components.ContainsKey(name)) result._components.Add(name, (kind, recovery, template, new(StringComparer.Ordinal)));
                IEnumerable<string> selected = capability.TryGetProperty("servers", out JsonElement scopes) ? scopes.EnumerateArray().Select(scope => scope.GetString()!) : servers.Keys;
                foreach (string server in selected.Where(servers.ContainsKey))
                {
                    result._components[name].Consumers.Add(servers[server]);
                    string key = capability.GetProperty("configurationKey").GetString()!.Replace(":", "__", StringComparison.Ordinal);
                    Dictionary<string, string> environment = result._environment[owner + "/" + server];
                    if (environment.TryGetValue(key, out string? previous) && previous != name) throw Failure(module, "runtime.dapr.configurationKey", $"conflicting binding for '{server}/{key}'");
                    environment[key] = name;
                }
            }
            foreach (JsonElement surface in module.Declaration.GetProperty("surfaces").GetProperty("interfaces").EnumerateArray())
            {
                if (!servers.TryGetValue(surface.GetProperty("server").GetString()!, out string? appId) || !surface.TryGetProperty("invocationRules", out JsonElement rules)) continue;
                foreach (JsonElement rule in rules.EnumerateArray())
                    result._rules[appId].Add((rule.GetProperty("caller").GetString()!, rule.GetProperty("path").GetString()!, rule.GetProperty("verbs").EnumerateArray().Select(verb => verb.GetString()!).ToArray()));
            }
            foreach (JsonElement topic in module.Declaration.GetProperty("integration").GetProperty("topics").EnumerateArray())
            {
                if (!topic.TryGetProperty("subscription", out JsonElement subscription)) continue;
                string server = subscription.GetProperty("server").GetString()!;
                if (!servers.TryGetValue(server, out string? appId)) continue;
                string component = Name("pubsub", topic.GetProperty("role").GetString()!);
                if (!result._components.TryGetValue(component, out var binding) || !binding.Consumers.Contains(appId)) throw Failure(module, "integration.topics.subscription.server", "receiver has no bound pubsub capability");
                string name = topic.GetProperty("name").GetString()!;
                JsonElement deadLetter = topic.GetProperty("deadLetter");
                string? target = deadLetter.GetProperty("strategy").GetString() == "topic"
                    ? PhysicalTopic(module.Declaration.GetProperty("integration").GetProperty("topics").EnumerateArray().First(candidate => candidate.GetProperty("name").GetString() == deadLetter.GetProperty("topic").GetString() && candidate.GetProperty("role").GetString() == topic.GetProperty("role").GetString())) : null;
                string identity = "platform-" + Convert.ToHexStringLower(SHA256.HashData(Encoding.UTF8.GetBytes(JsonSerializer.Serialize(new[] { owner, server, name, component, PhysicalTopic(topic) }))));
                result._subscriptions.Add((identity, component, PhysicalTopic(topic), subscription.GetProperty("route").GetString()!, appId, target));
            }
        }
        return result;
    }

    /// <summary>Returns the deterministic name of a logical component.</summary>
    public static string Name(string kind, string role) => (kind, role) switch
    {
        ("state", "state") => "statestore", ("pubsub", "events") => "pubsub",
        ("configuration", "rate-limit-configuration") => "configstore",
        ("state", "telemetry-state") => "access-telemetry-store",
        ("secret", "telemetry-secrets") => "access-telemetry-secrets",
        ("configuration", "telemetry-configuration") => "access-telemetry-config",
        ("secret", "secrets") => "secretstore", ("conversation", "conversation") => "llm",
        _ => "platform-" + kind + "-" + role,
    };

    /// <summary>Gets configuration consumed by one selected owner server.</summary>
    internal IReadOnlyDictionary<string, string> Environment(string owner, string server) => _environment[owner + "/" + server];

    /// <summary>Gets the Dapr component implementation type.</summary>
    internal string Type(string name) => _retentionProfile is not null && name == Name("state", "telemetry-state") ? "state.postgresql" : _components[name].Kind switch { "state" => "state.redis", "pubsub" => "pubsub.redis", "secret" => "secretstores.local.file", "configuration" => "configuration.redis", "conversation" => "conversation.echo", _ => throw new InvalidOperationException(name) };

    /// <summary>Gets the rendered filename for a resolved component.</summary>
    internal string FileName(string name) => name == Name("secret", "telemetry-secrets") ? "telemetry-secrets.yaml" : _components[name].Template;

    /// <summary>Checks whether an app consumes a component.</summary>
    internal bool Consumes(string name, string appId) => _components.TryGetValue(name, out var binding) && binding.Consumers.Contains(appId);

    /// <summary>Renders all components, receiver configurations and explicit subscriptions in memory.</summary>
    internal IReadOnlyDictionary<string, string> Render(string directory, int redisPort, int telemetryPort, string secretsPath, string? discovery, string? sentryAddress = null)
    {
        Dictionary<string, string> files = new(StringComparer.Ordinal);
        foreach (var (name, binding) in _components.Where(pair => pair.Value.Consumers.Count > 0))
        {
            if (_retentionProfile is not null && name == Name("state", "telemetry-state"))
            {
                files.Add(binding.Template, _retentionProfile.RenderComponent(binding.Consumers));
                continue;
            }
            string source = Path.Combine(directory, binding.Template);
            if (!File.Exists(source)) throw new FileNotFoundException($"{source}: runtime.dapr: Platform shared local Dapr component template is unavailable.", source);
            YamlMappingNode component;
            try
            {
                component = Parse(File.ReadAllText(source));
                if (Scalar(component, "apiVersion") != "dapr.io/v1alpha1" || Scalar(component, "kind") != "Component") throw new InvalidDataException("expected a dapr.io/v1alpha1 Component");
                YamlMappingNode metadata = Mapping(component, "metadata");
                _ = Scalar(metadata, "name");
                YamlMappingNode spec = Mapping(component, "spec");
                if (Scalar(spec, "type") != Type(name)) throw new InvalidDataException("component type differs from the bound capability");
                _ = Scalar(spec, "version");
                if (binding.Template == "secretstore.yaml")
                {
                    if (!spec.Children.TryGetValue(new YamlScalarNode("metadata"), out YamlNode? entries) || entries is not YamlSequenceNode sequence) throw new InvalidDataException("spec.metadata must be a sequence");
                    bool boundSecretsFile = false;
                    foreach (YamlNode entry in sequence.Children)
                    {
                        if (entry is not YamlMappingNode item) throw new InvalidDataException("spec.metadata entries must be mappings");
                        if (Scalar(item, "name") == "secretsFile")
                        {
                            item.Children[new YamlScalarNode("value")] = new YamlScalarNode(secretsPath);
                            boundSecretsFile = true;
                        }
                    }
                    if (!boundSecretsFile) throw new InvalidDataException("spec.metadata must contain a secretsFile entry");
                }
                metadata.Children[new YamlScalarNode("name")] = new YamlScalarNode(name);
                component.Children[new YamlScalarNode("scopes")] = new YamlSequenceNode(binding.Consumers.Order(StringComparer.Ordinal).Select(app => new YamlScalarNode(app)));
            }
            catch (Exception exception) when (exception is YamlDotNet.Core.YamlException or InvalidCastException or KeyNotFoundException or InvalidDataException)
            {
                throw new InvalidDataException($"{source}: runtime.dapr: invalid local component template: {exception.Message}", exception);
            }
            string content = Write(component).Replace("localhost:6379", "127.0.0.1:" + (binding.Template == "telemetry-state.yaml" ? telemetryPort : redisPort), StringComparison.Ordinal)
                .Replace("127.0.0.1:6379", "127.0.0.1:" + (binding.Template == "telemetry-state.yaml" ? telemetryPort : redisPort), StringComparison.Ordinal);
            files.Add(name == "access-telemetry-secrets" ? "telemetry-secrets.yaml" : binding.Template, content);
        }
        foreach (var (appId, rules) in _rules)
        {
            string content = JsonSerializer.Serialize(new { apiVersion = "dapr.io/v1alpha1", kind = "Configuration", metadata = new { name = "platform-" + appId }, spec = new { mtls = new { enabled = true, controlPlaneTrustDomain = "localhost", sentryAddress = sentryAddress ?? "localhost:50001" }, features = new[] { new { name = "HotReload", enabled = false } }, accessControl = AccessControl(appId, "default", "public") } });
            if (discovery is not null) content = PlatformAppModel.MergeRunDiscovery(content, discovery);
            files.Add("accesscontrol." + appId + ".yaml", content);
        }
        foreach (var subscription in _subscriptions)
            files.Add("subscription." + subscription.Name + ".yaml", JsonSerializer.Serialize(new { apiVersion = "dapr.io/v2alpha1", kind = "Subscription", metadata = new { name = subscription.Name }, spec = new { pubsubname = subscription.Component, topic = subscription.Topic, routes = new { @default = subscription.Route }, deadLetterTopic = subscription.DeadLetter }, scopes = new[] { subscription.AppId } }, new JsonSerializerOptions { DefaultIgnoreCondition = System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingNull }));
        return files;
    }

    /// <summary>Returns shared receiver ACLs with environment-selected trust and namespace.</summary>
    public JsonElement AccessControl(string appId, string applicationNamespace, string trustDomain)
    {
        var policies = _rules[appId].GroupBy(rule => rule.Caller, StringComparer.Ordinal).OrderBy(group => group.Key, StringComparer.Ordinal).Select(group =>
            {
                var operations = group.GroupBy(rule => rule.Path, StringComparer.OrdinalIgnoreCase).Select(path => new
                {
                    Path = path.Key.ToLowerInvariant(),
                    Verbs = path.SelectMany(rule => rule.Verbs).Distinct(StringComparer.Ordinal).Order(StringComparer.Ordinal).ToArray(),
                }).ToArray();
                return new
                {
                    appId = group.Key, @namespace = applicationNamespace, trustDomain, defaultAction = "deny",
                    // Dapr returns the first populated prefix node. Its single-stage fallback preserves
                    // a parent's base invocation while letting explicit descendants retain their verbs.
                    operations = operations.OrderByDescending(operation => operation.Path.Length).ThenBy(operation => operation.Path, StringComparer.Ordinal).Select(operation => new
                    {
                        name = operations.Any(other => other.Path != operation.Path && other.Path.StartsWith(operation.Path.TrimEnd('/') + "/", StringComparison.Ordinal)) ? operation.Path.TrimEnd('/') + "/*" : operation.Path,
                        httpVerb = operation.Verbs, action = "allow",
                    }).ToArray(),
                };
            }).ToArray();
        return JsonSerializer.SerializeToElement(new { defaultAction = "deny", trustDomain, policies });
    }

    /// <summary>Gets environment-owned capability requirements; no providers or credentials are selected.</summary>
    public object Capabilities => _components.Where(p => p.Value.Consumers.Count > 0).OrderBy(p => p.Key, StringComparer.Ordinal).Select(p => new
    {
        name = p.Key, kind = p.Value.Kind, recovery = p.Value.Recovery,
        consumers = p.Value.Consumers.Order(StringComparer.Ordinal).ToArray(),
    }).ToArray();

    /// <summary>Gets application-owned subscriptions, shared by local and hosted rendering.</summary>
    public object Subscriptions => _subscriptions.Select(s => new
    {
        name = s.Name, component = s.Component, topic = s.Topic, route = s.Route, appId = s.AppId, deadLetter = s.DeadLetter,
    }).ToArray();

    private static YamlMappingNode Parse(string content)
    {
        YamlStream yaml = new();
        yaml.Load(new StringReader(content));
        if (yaml.Documents.Count != 1 || yaml.Documents[0].RootNode is not YamlMappingNode root) throw new InvalidDataException("expected one YAML mapping document");
        return root;
    }
    private static YamlMappingNode Mapping(YamlMappingNode parent, string key) => parent.Children.TryGetValue(new YamlScalarNode(key), out YamlNode? value) && value is YamlMappingNode mapping ? mapping : throw new InvalidDataException($"{key} must be a mapping");
    private static string Scalar(YamlMappingNode parent, string key) => parent.Children.TryGetValue(new YamlScalarNode(key), out YamlNode? value) && value is YamlScalarNode { Value: { Length: > 0 } text } ? text : throw new InvalidDataException($"{key} must be a nonempty scalar");
    private static string PhysicalTopic(JsonElement topic) => topic.TryGetProperty("subscription", out JsonElement subscription) && subscription.TryGetProperty("topic", out JsonElement physical) ? physical.GetString()! : topic.GetProperty("name").GetString()!;
    private static string Write(YamlMappingNode root) { StringWriter writer = new(CultureInfo.InvariantCulture); new YamlStream(new YamlDocument(root)).Save(writer, false); return writer.ToString(); }
    private static InvalidDataException Failure(PlatformModuleDeclaration module, string field, string reason) => new($"{module.Source}: {field}: {reason}.");
}

namespace Hexalith.Platform.Composition;

using System.Globalization;
using System.Collections.Immutable;
using System.Security.Cryptography;
using System.Text.Json;
using Aspire.Hosting;
using Aspire.Hosting.ApplicationModel;
using CommunityToolkit.Aspire.Hosting.Dapr;
using Hexalith.Builds.Tooling.Runtime;
using Hexalith.Builds.Tooling.Workspace;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Aspire.Hosting.Lifecycle;
using YamlDotNet.RepresentationModel;

/// <summary>The single Platform-owned declaration composition used by the file AppHost and Builds.</summary>
public static class PlatformAppModel
{
    /// <summary>Routes the thin file entry while refusing incompatible local topologies.</summary>
    public static void ComposeEntry(IDistributedApplicationBuilder builder)
    {
        ArgumentNullException.ThrowIfNull(builder);
        if (builder.Configuration.GetValue<bool>("Platform:Hosted:Enabled"))
        {
            PlatformHostedPublishing.ComposeNativeProbe(builder);
            return;
        }
        if (bool.TryParse(builder.Configuration["Platform:Agents:Enabled"], out bool agents) && agents)
        {
            if (!AgentsHostComposition.TryCompose(builder))
                throw new InvalidOperationException("DependencyNotAvailable: EXT-HOST-1. Full Agents composition and accepted owner prerequisites are unavailable.");
            return;
        }
        bool works = bool.TryParse(builder.Configuration["Platform:Works:Enabled"], out bool selected) && selected;
        if (works && builder.Configuration.GetValue<bool>("Platform:Timesheets:Enabled"))
            throw new InvalidOperationException("Hexalith.Timesheets: Platform:Timesheets:Enabled cannot be combined with Platform:Works:Enabled; select one Development composition.");
        if (works) WorksPreviewModel.Compose(builder);
        else Compose(builder);
    }

    /// <summary>Validates and binds the complete set, without adding any resources.</summary>
    public static IReadOnlyList<PlatformServerBinding> Prepare(PlatformCompositionOptions options)
    {
        ArgumentNullException.ThrowIfNull(options);
        PlatformTimesheetsBinding.ValidateMode(options);
        return PlatformServerBindings.Resolve(options, PlatformDeclarationSet.Load(options));
    }

    /// <summary>Composes the thin file AppHost from the command's persisted source mapping.</summary>
    public static void Compose(IDistributedApplicationBuilder builder)
    {
        ArgumentNullException.ThrowIfNull(builder);
        bool timesheets = builder.Configuration.GetValue<bool>("Platform:Timesheets:Enabled");
        if (timesheets && (!builder.Environment.IsDevelopment() || !builder.ExecutionContext.IsRunMode))
            throw new InvalidOperationException("Hexalith.Timesheets: Platform:Timesheets:Enabled requires a Development run. A qualified release and production profile are unavailable.");
        if (!builder.Environment.IsDevelopment())
            throw new InvalidOperationException("Platform declaration composition requires a Development host. A production profile is unavailable.");
        string? active = builder.Configuration["Platform:ActiveModule"];
        if (active is not null && string.IsNullOrWhiteSpace(active)) throw new InvalidDataException("Platform:ActiveModule: module identity is empty.");
        string? declaration = builder.Configuration["Platform:DeclarationPath"];
        string? mappingPath = builder.Configuration["Platform:SourceMapping:Path"] ?? Environment.GetEnvironmentVariable("HEXALITH_SOURCE_MAPPING_PATH");
        string? hash = builder.Configuration["Platform:SourceMapping:Hash"] ?? Environment.GetEnvironmentVariable("HEXALITH_SOURCE_MAPPING_HASH");
        SourceMapping mapping = mappingPath is null
            ? WorkspaceRootResolver.ResolveAsync(declaration ?? Path.Combine(builder.AppHostDirectory, "hexalith-platform.json"), WorkspaceMode.Source, CancellationToken.None).GetAwaiter().GetResult()
            : SourceMapping.LoadVerified(mappingPath, hash ?? string.Empty);
        Compose(builder, new PlatformCompositionOptions { PlatformRoot = builder.AppHostDirectory, Mapping = mapping, ActiveModule = active, DeclarationPaths = declaration is null ? [] : [declaration], TimesheetsEnabled = timesheets, EventStoreSeedProject = builder.Configuration["Platform:EventStoreSeedProject"] });
    }

    /// <summary>Composes a v2 signed Builds plan, keeping its package-mode gateway seed.</summary>
    public static void ComposeRun(IDistributedApplicationBuilder builder, CompositionRunPlan plan, string signingKey, string? seedProject)
    {
        ArgumentNullException.ThrowIfNull(builder);
        ArgumentNullException.ThrowIfNull(plan);
        ComposeRun(builder, plan, signingKey, seedProject, static options => options);
    }

    internal static void ComposeRun(IDistributedApplicationBuilder builder, CompositionRunPlan plan, string signingKey, string? seedProject, Func<PlatformCompositionOptions, PlatformCompositionOptions> configureOptions)
    {
        SourceMapping mapping = plan.SourceMapping ?? throw new InvalidDataException("Platform v2 composition requires the command-resolved source mapping.");
        string root = mapping.PlatformIdentity?.PlatformPath ?? mapping.Entries.Single(e => e.Identity == "Hexalith.Platform").Path!;
        bool timesheets = PlatformTimesheetsBinding.SelectRun(plan, root, builder.Configuration.GetValue<bool>("Platform:Timesheets:Enabled"));
        Dictionary<string, string> configuration = new(StringComparer.Ordinal);
        foreach (string server in new[] { "parties/domain", "eventstore/gateway", "tenants/domain", "tenants/api", "memories/server", "memories/clock", "memories/telemetry" })
        {
            configuration[server + "/Authentication:JwtBearer:SigningKey"] = signingKey;
            configuration[server + "/Authentication:JwtBearer:Issuer"] = CompositionEnvironment.TokenIssuer;
            configuration[server + "/Authentication:JwtBearer:Audience"] = CompositionEnvironment.TokenAudience;
            configuration[server + "/Authentication:JwtBearer:ValidAudiences"] = JsonSerializer.Serialize(new[] { CompositionEnvironment.TokenAudience });
        }
        foreach (string server in new[] { "tenants/domain", "tenants/api" })
        {
            configuration[server + "/EventStore:Authentication:SigningKey"] = signingKey;
            configuration[server + "/EventStore:Authentication:Issuer"] = CompositionEnvironment.TokenIssuer;
            configuration[server + "/EventStore:Authentication:Audience"] = CompositionEnvironment.TokenAudience;
            configuration[server + "/Jwt:SigningKey"] = signingKey;
        }
        Compose(builder, configureOptions(new PlatformCompositionOptions
        {
            PlatformRoot = root, Mapping = mapping, DeclarationPaths = plan.PlatformDeclarationPaths,
            ActiveModule = plan.PlatformActiveModule, EventStoreSeedProject = seedProject, Configuration = configuration, RunPlan = plan,
            TimesheetsEnabled = timesheets, RetentionProfile = PlatformRetentionProfile.Select(plan, root),
        }));
    }

    /// <summary>Adds exactly the prepared environment, with owner readiness and lifecycle metadata.</summary>
    public static void Compose(IDistributedApplicationBuilder builder, PlatformCompositionOptions options)
    {
        ArgumentNullException.ThrowIfNull(builder);
        ArgumentNullException.ThrowIfNull(options);
        if (options.TimesheetsEnabled && (!builder.Environment.IsDevelopment() || !builder.ExecutionContext.IsRunMode))
            throw new InvalidOperationException("Hexalith.Timesheets: Platform:Timesheets:Enabled requires a Development run. A qualified release and production profile are unavailable.");
        PlatformTimesheetsBinding.ValidateMode(options);
        if (options.RetentionProfile is not null && (!builder.Environment.IsDevelopment() || options.Mapping.Mode != WorkspaceMode.Source || options.RunPlan is null))
            throw new InvalidDataException("The PostgreSQL retention experiment requires a runner-owned Development source run.");
        if (options.RetentionProfile is { } retentionObserver) builder.Services.AddSingleton<ICompositionTestObservationProvider>(retentionObserver);
        HashSet<IResource> existingResources = [.. builder.Resources];
        var declarations = PlatformDeclarationSet.Load(options);
        PlatformDaprBindings dapr = PlatformDaprBindings.Resolve(declarations, options.RetentionProfile);
        IReadOnlyList<PlatformServerBinding> servers = PlatformServerBindings.Resolve(options, declarations, dapr);
        foreach (PlatformServerBinding server in servers.Where(s => s.Image is not null))
        {
            System.Diagnostics.ProcessStartInfo probe = CompositionProcess.CreateStartInfo("docker", ["manifest", "inspect", server.Image!], options.PlatformRoot, null);
            CompositionProcessResult result = options.ImageProbeRunner(probe, TimeSpan.FromSeconds(20), CancellationToken.None).GetAwaiter().GetResult();
            if (result.ExitCode != 0 || result.TimedOut) throw new InvalidDataException($"{server.Module.Source}: {PlatformDeclarationSet.Id(server.Module.Declaration)}/{server.ServerId}: image '{server.Image}' is unavailable from its released registry.");
        }
        string components = options.ComponentsDirectory ?? Path.Combine(options.PlatformRoot, "DaprComponents", "reference");
        string? selectedDaprHome = options.RunPlan?.DaprHome ?? Environment.GetEnvironmentVariable("HEXALITH_DAPR_HOME");
        string daprHome = selectedDaprHome ?? Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);
        bool hasMemories = servers.Any(server => PlatformDeclarationSet.Id(server.Module.Declaration) == "memories");
        bool hasGateway = servers.Any(server => server.ResourceId == "eventstore");
        bool hasTimesheets = servers.Any(server => server.ResourceId == "timesheets");
        string rendered = options.RunPlan is null ? Path.Combine(Path.GetTempPath(), "hexalith-platform", Guid.NewGuid().ToString("N")) : Path.Combine(options.RunPlan.Workspace, "platform-components");
        CompositionWorkspace.CreatePrivateDirectory(Path.GetDirectoryName(rendered)!);
        CompositionWorkspace.CreatePrivateDirectory(rendered);
        try
        {
            CompositionRunPorts localPorts = AllocateOwnedSecondaryPorts(Math.Max(1, servers.Count(server => server.ResourceId != "eventstore")), options.RunPlan);
            int redisPort = options.RunPlan?.Ports.Redis ?? localPorts.Redis;
            int vectorPort = localPorts.UiHttp;
            int sentryPort = localPorts.PlacementHealth;
            int placementPort = options.RunPlan?.Ports.Placement ?? localPorts.Placement;
            int schedulerPort = options.RunPlan?.Ports.Scheduler ?? localPorts.Scheduler;
            string sentryAddress = "localhost:" + sentryPort;
            string placementAddress = "localhost:" + placementPort;
            string schedulerAddress = "localhost:" + schedulerPort;
            string discovery = options.RunPlan is null
                ? CompositionDaprComponentRenderer.RenderConfiguration("platform-" + Path.GetFileName(rendered), rendered)
                : File.ReadAllText(options.RunPlan.DaprConfigPath);
            string mappingWorkspace = options.RunPlan?.Workspace ?? rendered;
            SourceMappingMaterializer.WriteAsync(options.Mapping, mappingWorkspace, CancellationToken.None).GetAwaiter().GetResult();
            options.RetentionProfile?.Prepare(rendered, localPorts.Redis);
            using ECDsa clockKey = ECDsa.Create(ECCurve.NamedCurves.nistP256);
            string secrets = Path.Combine(rendered, "secrets.json");
            File.WriteAllText(secrets, JsonSerializer.Serialize(new Dictionary<string, object>
            {
                ["access-telemetry-clock-key"] = Convert.ToBase64String(clockKey.ExportPkcs8PrivateKey()),
                ["access-telemetry-marker-key"] = Convert.ToBase64String(RandomNumberGenerator.GetBytes(32)),
            }));
            if (!OperatingSystem.IsWindows()) File.SetUnixFileMode(secrets, UnixFileMode.UserRead | UnixFileMode.UserWrite);
            IReadOnlyDictionary<string, string> daprFiles = dapr.Render(components, redisPort, vectorPort, secrets, discovery, sentryAddress);
            string subscriptionsDirectory = Path.Combine(rendered, "subscriptions");
            bool hasSubscriptions = daprFiles.Keys.Any(file => file.StartsWith("subscription.", StringComparison.Ordinal));
            if (hasSubscriptions) CompositionWorkspace.CreatePrivateDirectory(subscriptionsDirectory);
            foreach (var file in daprFiles) File.WriteAllText(Path.Combine(file.Key.StartsWith("subscription.", StringComparison.Ordinal) ? subscriptionsDirectory : rendered, file.Key), file.Value);
            string sentryConfiguration = Path.Combine(rendered, "sentry.yaml");
            File.WriteAllText(sentryConfiguration, "apiVersion: dapr.io/v1alpha1\nkind: Configuration\nmetadata:\n  name: platform-sentry\nspec:\n  mtls:\n    enabled: true\n    workloadCertTTL: 24h\n");
            if (hasTimesheets) File.WriteAllText(Path.Combine(rendered, "timesheets-readmodels.yaml"), File.ReadAllText(Path.Combine(components, "timesheets-readmodels.yaml")).Replace("localhost:6379", "127.0.0.1:" + redisPort, StringComparison.Ordinal));

            string schedulerData = Path.Combine(rendered, "scheduler-data");
            CompositionWorkspace.CreatePrivateDirectory(schedulerData);
